aidr-claude/.claude-plugin/plugin.json:
{
  "name": "aidr-claude",
  "version": "0.1.4",
  "description": "Agent Manager: Agent Manager Hook integration for Claude Code.",
  "author": {
    "name": "Agent Manager"
  }
}

aidr-claude/scripts/bridge.sh:
#!/bin/sh
set -eu
fail() {
  if [ "${1:-}" = "PreToolUse" ]; then
    printf '%s\n' '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"deny","permissionDecisionReason":"aidr_hook_binary_unavailable"}}'
    exit 0
  fi
  printf '%s\n' 'aidr_hook_binary_unavailable' >&2
  exit 1
}
case "${AIDR_CLIENT_BIN:-}" in
  /*) ;;
  *) fail "${1:-}" ;;
esac
if [ ! -x "$AIDR_CLIENT_BIN" ]; then
  fail "${1:-}"
fi
exec "$AIDR_CLIENT_BIN" aidr-hook --agent claude --event "$1"

